<?php
/**
 * ChatHelp — dump-fototest (UCTAN UCA TEST) — foto okuma backend'ini gercek
 *  bir belge gorseliyle (Almanca "Mahnung" mektubu, 420x200 PNG) sunucu
 *  uzerinden dener: api.php?action=analyze_photo'ya POST atar; HTTP kodu,
 *  hata, sonuc alanlari ve ozet gorunur. Boylece foto sorunu BACKEND mi
 *  FRONTEND mi KESIN ayrilir. (1 gercek AI-vision cagrisi; veri YAZMAZ.)
 * KULLANIM: pull2.php?key=...&files=dump-fototest.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
@set_time_limit(180);
echo "=== dump-fototest — analyze_photo uctan uca ===\n\n";

$host = $_SERVER['HTTP_HOST'] ?? 'chat-help.com';
$dir  = rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? '/chat/x.php'), '/');
$url  = 'https://'.$host.$dir.'/api.php?action=analyze_photo';

$b64 = '';
echo "test gorseli: ".strlen($b64)." B base64 (PNG, Almanca Mahnung mektubu)\n";
echo "hedef: $url\n\n";

$c=curl_init($url);
curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>150,CURLOPT_CONNECTTIMEOUT=>15,
  CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['b64'=>$b64,'mime'=>'image/png','lang'=>'de']),
  CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_USERAGENT=>'ChatHelp-fototest/1.0']);
$body=curl_exec($c); $code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE); $err=curl_error($c); curl_close($c);

if($body===false||$body===''){ exit("✗ HTTP $code — govde yok".($err?" ($err)":"")."\n\nSONUC: BACKEND ULASILAMIYOR.\n"); }
echo "HTTP $code — govde ".strlen($body)." B\n\n";
$j=json_decode($body,true);
if(!is_array($j)){ exit("✗ JSON degil, ilk 400:\n".substr($body,0,400)."\n\nSONUC: BACKEND BOZUK (JSON dondurmuyor).\n"); }
if(!empty($j['error'])){ exit("✗ API HATASI: ".$j['error']."\n\nSONUC: BACKEND HATA VERIYOR — duzeltilecek.\n"); }

$r = $j['result'] ?? $j['ocr'] ?? null;
echo "ust anahtarlar: ".implode(', ',array_keys($j))."\n";
if(is_array($r)){
  echo "result anahtarlari: ".implode(', ',array_keys($r))."\n\n";
  foreach($r as $k=>$v){ if(is_scalar($v)) echo "  ".str_pad($k,16).": ".mb_substr(preg_replace('/\s+/',' ',(string)$v),0,160)."\n"; }
  $sum=(string)($r['zusammenfassung'] ?? $r['summary'] ?? '');
  echo "\n".(mb_strlen($sum)>10 ? "SONUC: BACKEND CALISIYOR ✓ — belge okundu, ozet uretti.\n   -> Foto hala calismiyorsa sorun FRONTEND'te (once apply-fix-sw.php calistirilmali,\n      sonra sayfa 1-2 kez yenilenmeli; App'te App'i tamamen kapatip acin).\n" : "⚠ Backend yanit verdi ama ozet bos/kisa — cikti yukarida.\n");
}else{
  echo "govde (ilk 600):\n".mb_substr(preg_replace('/\s+/',' ',$body),0,600)."\n";
  echo "\n⚠ result/ocr alani yok — yapiyi yukaridan degerlendirecegim, ciktinin tamamini gonder.\n";
}
